CREATE DATABASE IF NOT EXISTS studytrack_final
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE studytrack_final;


CREATE TABLE IF NOT EXISTS usuario (
    id_usuario INT NOT NULL AUTO_INCREMENT,
    nome_usuario VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL,
    senha VARCHAR(255) NOT NULL,
    PRIMARY KEY (id_usuario),
    CONSTRAINT uq_usuario_email UNIQUE (email)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS aluno (
    id_aluno INT NOT NULL AUTO_INCREMENT,
    id_usuario INT NOT NULL,
    matricula VARCHAR(30) NOT NULL,
    turma VARCHAR(30) NOT NULL,
    curso VARCHAR(100) NOT NULL,
    PRIMARY KEY (id_aluno),
    CONSTRAINT uq_aluno_usuario UNIQUE (id_usuario),
    CONSTRAINT uq_aluno_matricula UNIQUE (matricula),
    CONSTRAINT fk_aluno_usuario
        FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS disciplina (
    id_disciplina INT NOT NULL AUTO_INCREMENT,
    nome_disciplina VARCHAR(100) NOT NULL,
    descricao_disciplina JSON NULL,
    PRIMARY KEY (id_disciplina)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS material (
    id_material INT NOT NULL AUTO_INCREMENT,
    nome_material VARCHAR(150) NOT NULL,
    tipo VARCHAR(50) NOT NULL,
    descricao_material JSON NULL,
    link VARCHAR(500) NULL,
    categoria VARCHAR(80) NULL,
    autor VARCHAR(150) NULL,
    PRIMARY KEY (id_material)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS plano_estudo (
    id_plano INT NOT NULL AUTO_INCREMENT,
    id_aluno INT NOT NULL,
    nome_plano VARCHAR(120) NOT NULL,
    objetivo VARCHAR(255) NOT NULL,
    descricao JSON NULL,
    data_inicio DATE NOT NULL,
    data_fim DATE NULL,
    PRIMARY KEY (id_plano),
    CONSTRAINT chk_plano_datas
        CHECK (data_fim IS NULL OR data_fim >= data_inicio),
    CONSTRAINT fk_plano_aluno
        FOREIGN KEY (id_aluno) REFERENCES aluno(id_aluno)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS atividade (
    id_atividade INT NOT NULL AUTO_INCREMENT,
    id_plano INT NOT NULL,
    id_disciplina INT NOT NULL,
    titulo JSON NOT NULL,
    descricao VARCHAR(500) NULL,
    prazo DATE NULL,
    prioridade VARCHAR(20) NOT NULL DEFAULT 'media',
    status VARCHAR(30) NOT NULL DEFAULT 'pendente',
    PRIMARY KEY (id_atividade),
    CONSTRAINT chk_atividade_prioridade
        CHECK (prioridade IN ('baixa', 'media', 'alta')),
    CONSTRAINT chk_atividade_status
        CHECK (status IN ('pendente', 'em andamento', 'concluida')),
    CONSTRAINT fk_atividade_plano
        FOREIGN KEY (id_plano) REFERENCES plano_estudo(id_plano)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_atividade_disciplina
        FOREIGN KEY (id_disciplina) REFERENCES disciplina(id_disciplina)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS atividade_material (
    id_atividade INT NOT NULL,
    id_material INT NOT NULL,
    PRIMARY KEY (id_atividade, id_material),
    CONSTRAINT fk_am_atividade
        FOREIGN KEY (id_atividade) REFERENCES atividade(id_atividade)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_am_material
        FOREIGN KEY (id_material) REFERENCES material(id_material)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;










SELECT 'usuario' AS tabela, COUNT(*) AS quantidade FROM usuario
UNION ALL SELECT 'aluno', COUNT(*) FROM aluno
UNION ALL SELECT 'disciplina', COUNT(*) FROM disciplina
UNION ALL SELECT 'material', COUNT(*) FROM material
UNION ALL SELECT 'plano_estudo', COUNT(*) FROM plano_estudo
UNION ALL SELECT 'atividade', COUNT(*) FROM atividade
UNION ALL SELECT 'atividade_material', COUNT(*) FROM atividade_material;

SELECT
    (SELECT COUNT(*) FROM usuario) +
    (SELECT COUNT(*) FROM aluno) +
    (SELECT COUNT(*) FROM disciplina) +
    (SELECT COUNT(*) FROM material) +
    (SELECT COUNT(*) FROM plano_estudo) +
    (SELECT COUNT(*) FROM atividade) +
    (SELECT COUNT(*) FROM atividade_material) AS total_registros;
    